// 删除顺序表中所有值为 x 的元素，O(n)/O(1)
int k = 0;
for (int i = 0; i < L.length; ++i)
    if (L.data[i] != x) L.data[k++] = L.data[i];
L.length = k;

// 带头结点单链表就地逆置
LNode *p = L->next, *q;
L->next = NULL;
while (p) { q = p->next; p->next = L->next; L->next = p; p = q; }

// 找未出现的最小正整数，O(n)/O(1)
for (int i = 0; i < n; ++i)
    while (A[i] > 0 && A[i] <= n && A[A[i]-1] != A[i])
        swap(A[i], A[A[i]-1]);
for (int i = 0; i < n; ++i) if (A[i] != i+1) return i+1;
return n+1;
